          helpText: ["Write a few sentences for each measure. Many teams rate each one Low, Medium or High with a reason; you may do that or write it in your own words. At least 20 characters each.", "Schreiben Sie für jede Maßnahme ein paar Sätze. Viele Teams bewerten jede mit Niedrig, Mittel oder Hoch und einem Grund; Sie können das so machen oder es in eigenen Worten schreiben. Mindestens 20 Zeichen je Maßnahme."],
          helpTable: ["One row per measure: say the impact, the effort and the risk in a few words.", "Eine Zeile pro Maßnahme: Nennen Sie die Wirkung, den Aufwand und das Risiko in wenigen Worten."],
          firstCol: ["Measure", "Maßnahme"], itemWord: ["assess measure", "bewerten Sie Maßnahme"], minText: 20,
          missing: ["assess each measure: its impact, effort and risk", "bewerten Sie jede Maßnahme: Wirkung, Aufwand und Risiko"],
          items: [["A", ["Measure A · Simplify the content", "Maßnahme A · Inhalte vereinfachen"]], ["B", ["Measure B · Improve the navigation", "Maßnahme B · Navigation verbessern"]], ["C", ["Measure C · Add additional functions", "Maßnahme C · Zusätzliche Funktionen ergänzen"]]],
          cols: [["impact", ["Impact", "Wirkung"]], ["effort", ["Effort", "Aufwand"]], ["risk", ["Risk", "Risiko"]]],
          hints: { first: ["the measure you assess", "die Maßnahme, die Sie bewerten"], impact: ["how much it helps learners understand and keep going", "wie sehr sie Lernenden hilft, zu verstehen und weiterzumachen"], effort: ["how much work and how many people it needs", "wie viel Arbeit und wie viele Personen sie braucht"], risk: ["what could go wrong or take longer than the time allows", "was schiefgehen oder länger dauern könnte, als die Zeit erlaubt"] },
          exFirst: ["Plainer signs in a hospital", "Schlichtere Schilder in einem Krankenhaus"],
          exCells: { impact: ["High: visitors find the wards at once.", "Hoch: Besucher finden die Stationen sofort."], effort: ["Low: new signs are printed.", "Niedrig: Neue Schilder werden gedruckt."], risk: ["Low: nothing else changes.", "Niedrig: Nichts anderes ändert sich."] },
          scale: ["impact", "effort", "risk"],
          doc: ["Assessment of the three measures", "Bewertung der drei Maßnahmen"],
